import React, {useMemo, useState} from 'react';
import './App.css';

const API_BASE = process.env.REACT_APP_PAYMENT_API || 'https://api.fawleydogshow.com';

const pedigreeTickets = [
  {name: 'Any Puppy (6-12 mths)', key: 'any_puppy', price: 5},
  {name: 'Any Junior (12-18 mths)', key: 'any_junior', price: 5},
  {name: 'Any Gundog', key: 'any_gundog', price: 5},
  {name: 'Any Utility', key: 'any_utility', price: 5},
  {name: 'Any Hound', key: 'any_hound', price: 5},
  {name: 'Any Toy', key: 'any_toy', price: 5},
  {name: 'Any Working', key: 'any_working', price: 5},
  {name: 'Any Pastoral', key: 'any_pastoral', price: 5},
  {name: 'Any Terrier', key: 'any_terrier', price: 5},
  {name: 'Any Open', key: 'any_open', price: 5},
  {name: 'Any Veteran', key: 'any_veteran', price: 5},
  {name: 'Junior Handler (U16)', key: 'junior_handler', price: 5},
];

const allDogTickets = [
  {name: 'Puppy', key: 'puppy', price: 4},
  {name: 'Prettiest', key: 'prettiest', price: 4},
  {name: 'Best Condition', key: 'best_condition', price: 4},
  {name: 'Best Rescue', key: 'best_rescue', price: 4},
  {name: 'Waggiest Tail', key: 'waggiest_tale', price: 4},
  {name: "Child's Best Friend", key: 'childs_best_friend', price: 4},
  {name: 'Fancy Dress', key: 'fancy_dress', price: 4},
  {name: 'Handsome', key: 'handsome', price: 4},
  {name: 'Fluffiest', key: 'fluffiest', price: 4},
  {name: 'Scruffiest', key: 'scruffiest', price: 4},
  {name: 'Smooth', key: 'smooth', price: 4},
  {name: 'Looks Like Owner', key: 'looks_like_owner', price: 4},
  {name: 'Obedience', key: 'obedience', price: 4},
  {name: 'Golden Oldie', key: 'golden_oldie', price: 4},
];

const buildTicketPayload = (quantities, ticketList) => {
  return ticketList.reduce((payload, ticket) => {
    const quantity = quantities[ticket.key] || 0;
    if (quantity > 0) {
      payload[ticket.key] = quantity;
    }
    return payload;
  }, {});
};

function App() {
  const [quantities, setQuantities] = useState({});
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [loading, setLoading] = useState(false);

  const totalAmount = useMemo(() => {
    const ticketSum = [...pedigreeTickets, ...allDogTickets].reduce((sum, ticket) => {
      const quantity = quantities[ticket.key] || 0;
      return sum + ticket.price * quantity;
    }, 0);
    return ticketSum * 100;
  }, [quantities]);

  const selectedCount = useMemo(
    () => Object.values(quantities).reduce((sum, value) => sum + (value || 0), 0),
    [quantities]
  );

  const handleQuantity = (ticketKey, delta) => {
    setQuantities((prev) => {
      const current = prev[ticketKey] || 0;
      const next = Math.max(0, current + delta);
      return next === 0 ? Object.fromEntries(Object.entries(prev).filter(([key]) => key !== ticketKey)) : {...prev, [ticketKey]: next};
    });
    setErrorMessage('');
  };

  const handleCheckout = async () => {
    if (selectedCount === 0) {
      setErrorMessage('Select at least one class before checking out.');
      return;
    }

    setLoading(true);
    setErrorMessage('');

    const payload = {
      first_name: firstName.trim(),
      last_name: lastName.trim(),
      email_address: email.trim(),
      doggie_info: {},
      pedigree_tickets: buildTicketPayload(quantities, pedigreeTickets),
      all_dog_tickets: buildTicketPayload(quantities, allDogTickets),
    };

    try {
      const response = await fetch(`${API_BASE}/payment/create`, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(payload),
      });
      const data = await response.json();

      if (!response.ok) {
        setErrorMessage(data.detail || data.message || 'Failed to start checkout.');
        return;
      }

      if (data.url) {
        window.location.href = data.url;
      } else {
        setErrorMessage('Stripe checkout URL was not returned.');
      }
    } catch (error) {
      setErrorMessage('Unable to connect to payment service. Try again in a moment.');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="app-shell">
      <header className="hero">
        <p className="eyebrow">Fawley Waterside Dog Show</p>
        <h1>Class Ticket Checkout</h1>
        <p className="tagline">Mobile-first ticket selection with Stripe checkout and no account required.</p>
        <div className="pill-row">
          <span className="pill">Fast mobile flow</span>
          <span className="pill">No login needed</span>
          <span className="pill">Stripe secure payment</span>
        </div>
      </header>

      <section className="section">
        <div className="section-header">
          <div>
            <h2>Choose your classes</h2>
            <p className="section-copy">Tap quantities for the classes you want, then complete payment.</p>
          </div>
          <span className="badge">{selectedCount} selected</span>
        </div>
        <div className="ticket-grid">
          {pedigreeTickets.map((ticket) => {
            const quantity = quantities[ticket.key] || 0;
            return (
              <article key={ticket.key} className={`ticket-card ${quantity > 0 ? 'selected' : ''}`}>
                <div>
                  <p className="ticket-type">{ticket.name}</p>
                  <p className="ticket-price">£{ticket.price}</p>
                </div>
                <div className="quantity-control">
                  <button
                    className="qty-btn"
                    type="button"
                    aria-label={`Remove one ${ticket.name}`}
                    onClick={() => handleQuantity(ticket.key, -1)}
                    disabled={quantity === 0}
                  >
                    −
                  </button>
                  <span className="qty-count">{quantity}</span>
                  <button
                    className="qty-btn"
                    type="button"
                    aria-label={`Add one ${ticket.name}`}
                    onClick={() => handleQuantity(ticket.key, 1)}
                  >
                    +
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      </section>

      <section className="section">
        <div className="section-header">
          <div>
            <h2>All Dog classes</h2>
            <p className="section-copy">Optional extra classes for every dog entry.</p>
          </div>
          <span className="badge">£4 per class</span>
        </div>
        <div className="ticket-grid">
          {allDogTickets.map((ticket) => {
            const quantity = quantities[ticket.key] || 0;
            return (
              <article key={ticket.key} className={`ticket-card ${quantity > 0 ? 'selected' : ''}`}>
                <div>
                  <p className="ticket-type">{ticket.name}</p>
                  <p className="ticket-price">£{ticket.price}</p>
                </div>
                <div className="quantity-control">
                  <button
                    className="qty-btn"
                    type="button"
                    aria-label={`Remove one ${ticket.name}`}
                    onClick={() => handleQuantity(ticket.key, -1)}
                    disabled={quantity === 0}
                  >
                    −
                  </button>
                  <span className="qty-count">{quantity}</span>
                  <button
                    className="qty-btn"
                    type="button"
                    aria-label={`Add one ${ticket.name}`}
                    onClick={() => handleQuantity(ticket.key, 1)}
                  >
                    +
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      </section>

      <section className="section contact-section">
        <h2>Contact details</h2>
        <p className="section-copy">Optional fields help the event team with your order confirmation.</p>
        <div className="contact-grid">
          <label className="field">
            <span>First name</span>
            <input
              type="text"
              value={firstName}
              onChange={(event) => setFirstName(event.target.value)}
              placeholder="Optional"
            />
          </label>
          <label className="field">
            <span>Last name</span>
            <input
              type="text"
              value={lastName}
              onChange={(event) => setLastName(event.target.value)}
              placeholder="Optional"
            />
          </label>
          <label className="field">
            <span>Email</span>
            <input
              type="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              placeholder="Optional for receipt"
            />
          </label>
        </div>
      </section>

      <aside className="summary-sheet">
        <div className="summary-row">
          <span>Selected classes</span>
          <strong>{selectedCount}</strong>
        </div>
        <div className="summary-row">
          <span>Payment total</span>
          <strong>£{(totalAmount / 100).toFixed(2)}</strong>
        </div>
        <button className="checkout-button" type="button" onClick={handleCheckout} disabled={loading}>
          {loading ? 'Starting payment...' : `Pay £${(totalAmount / 100).toFixed(2)}`}
        </button>
        <p className="summary-note">Secure Stripe checkout. No account creation required.</p>
        {errorMessage && <p className="status error">{errorMessage}</p>}
      </aside>
    </main>
  );
}

export default App;
